   }
   s.layout.EnterRoom("Floor01");Place(50,1.01f);var entry=Legacy(SchoolAction.EquipmentDoor,"EquipmentRoom");entry.Interact();yield return Wait(.15f);yield return Until(()=>s.layout.CurrentRoom=="EquipmentRoom"&&!Controls.IsLocked());yield return Drain(()=>s.Busy);yield return Gate("Equipment_Door_BtoA");
   s.layout.EnterRoom("Floor03Right");Place(49.2f,32.51f);yield return WalkTo(47);Check(s.layout.CurrentRoom=="ReadingPassage","right reading reverse walk "+v);Place(27.2f,32.51f);yield return WalkTo(25);Check(s.layout.CurrentRoom=="Floor03Left","left reading reverse walk "+v);
   if(memory){s.layout.EnterRoom("Floor01");Place(66.7f,1.01f);yield return Shot("51_CourtStudents");P05EvidenceRecorder.Begin(this,"08_CourtLife",17);yield return SampleLife(17.1f);s.layout.EnterRoom("Floor02");Place(24,17.23f);yield return Hold(.5f,KeyCode.A);yield return Hold(.5f,KeyCode.D);VisibleFeet("corridor after turn");yield return Shot("52_CorridorTurn");Rt.GetComponent<GamePause>().SetPaused(true);yield return new WaitForSecondsRealtime(.3f);Rt.GetComponent<GamePause>().SetPaused(false);VisibleFeet("corridor pause resume");yield return Shot("53_CorridorPauseResume");P05EvidenceRecorder.Begin(this,"09_CorridorLife",17);yield return SampleLife(17.1f);Check(s.layout.GetComponentsInChildren<P05PaintedLoop>(true).Count(l=>l.gameObject.activeInHierarchy&&l.identity.StartsWith("S")&&l.activity=="conversation")==6,"six distinct corridor students");Check(!s.layout.GetComponentsInChildren<TextMesh>(true).Any(t=>t.gameObject.activeInHierarchy&&(t.text=="张若媛"||t.text=="教导主任")),"no floating character name labels");}
  }
