 IEnumerator SampleLife(float seconds){
 var loops=School.layout.GetComponentsInChildren<P05PaintedLoop>(true).Where(l=>l.isActiveAndEnabled).ToArray();
 var starts=loops.Select(l=>l.transform.position).ToArray();var scales=loops.Select(l=>l.transform.localScale).ToArray();
 bool stable=true,anchored=true,pinned=true;var ranges=new float[loops.Length];float elapsed=0;
 while(elapsed<seconds){if(GamePause.IsPaused)yield return Foreground();elapsed+=GameplayClock.Delta;
  for(int i=0;i<loops.Length;i++){var l=loops[i];stable&=l.UsesStableSource&&l.VisualActive;anchored&=Vector3.Distance(starts[i],l.transform.position)<.00001f&&Vector3.Distance(scales[i],l.transform.localScale)<.00001f;pinned&=l.FurnitureDrift<.000001f&&l.SoleDrift<.000001f;ranges[i]=Mathf.Max(ranges[i],l.MotionRange);}yield return null;}
 Check(stable,"NPC complete source painting never switched or flashed");Check(anchored,"NPC world roots and scale remain fixed");Check(pinned,"desks chairs monitors and shoe vertices remain pinned");
 for(int i=0;i<loops.Length;i++)Check(ranges[i]>.00005f,"continuous local motion observed "+loops[i].identity+" range="+ranges[i]);
 }
