 void VisibleFeet(string label){var rig=Player.GetComponent<P02ActorPresentation>().Rig;if(!rig)return;var y=Camera.main.WorldToViewportPoint(rig.transform.position).y;Check(y>.105f&&y<.45f,"visible feet above letterbox "+label+" y="+y);}
 void FloorData(string name){
 var col=Player.GetComponent<Collider2D>();var rig=Player.GetComponent<P02ActorPresentation>().Rig;
 var lines=new List<string>{"actor="+Player.transform.position+" scale="+Player.transform.lossyScale+" body="+EditorJsonUtility.ToJson(Player.GetComponent<Rigidbody2D>()),"collider="+col.bounds+" "+EditorJsonUtility.ToJson(col),"rigfoot="+(rig?rig.transform.position:Vector3.zero),"camera="+Camera.main.transform.position};
 foreach(var r in Player.GetComponentsInChildren<SpriteRenderer>(true).Where(r=>!r.GetComponentInParent<P02CharacterRig>()))lines.Add("source="+r.name+" sprite="+(r.sprite?r.sprite.name:"")+" min="+r.bounds.min+" scale="+r.transform.lossyScale);
 var rb=Player.GetComponent<Rigidbody2D>();lines.Add("bodyPosition="+rb.position+" velocity="+rb.linearVelocity+" layer="+Player.gameObject.layer+" sleeping="+rb.IsSleeping());
 foreach(var c in Player.GetComponentsInChildren<Collider2D>(true))lines.Add("allshape="+c.name+" enabled="+c.enabled+" active="+c.gameObject.activeInHierarchy+" trigger="+c.isTrigger+" bounds="+c.bounds);
 var contacts=new ContactPoint2D[32];int count=rb.GetContacts(contacts);for(int i=0;i<count;i++){var q=contacts[i];lines.Add("contact="+q.collider.name+" other="+q.otherCollider.name+" point="+q.point+" normal="+q.normal+" separation="+q.separation);}
 foreach(var m in Player.GetComponents<MonoBehaviour>())lines.Add("component="+m.GetType().Name+" enabled="+m.enabled);
 foreach(var hit in Physics2D.RaycastAll(new Vector2(Player.transform.position.x,18),Vector2.down,4))lines.Add("hit="+hit.collider.name+" scene="+hit.collider.gameObject.scene.name+" trigger="+hit.collider.isTrigger+" layer="+hit.collider.gameObject.layer+" ignored="+Physics2D.GetIgnoreCollision(col,hit.collider)+" point="+hit.point+" normal="+hit.normal+" bounds="+hit.collider.bounds);
 File.WriteAllLines(folder+"/"+name+".txt",lines);
 }
