 IEnumerator CameraWorld(SchoolWorldVariant target){
 var chase=School.chase;var camera=Rt.GetComponent<CameraModeController>();
 if(School.layout.Variant==target)yield break;
 yield return Pulse(KeyCode.Q);yield return Until(()=>camera.IsRaised&&Rt.GetComponent<P02ToolMotion>().CameraReady,8);
 yield return new WaitForEndOfFrame();
 Check(chase.IsPreviewing,"original Q camera preview opens");
 Check(!School.layout.GetComponentsInChildren<P05PaintedLoop>(true).Any(l=>l.VisualActive),"continuous NPC meshes hidden at rendered camera-preview frame: "+string.Join(",",School.layout.GetComponentsInChildren<P05PaintedLoop>(true).Where(l=>l.VisualActive).Select(l=>l.identity+" active="+l.gameObject.activeInHierarchy+" chaseMatch="+(Field(l,"chase")==chase))));
 yield return Pulse(KeyCode.Space);yield return Until(()=>!camera.IsRaised&&!camera.IsBusy&&!Controls.IsLocked(),8);
 Need(School.layout.Variant==target,"original Space capture commits world "+target+" refusal="+chase.LastSwitchRefusal);
 Need(GroundedPlacement.IsSupported(Player),"camera switching stays on actual floor");
 }
 IEnumerator RunTo(float x){
 Label("original sprint route to "+x);Input(KeyCode.LeftShift,x>Player.transform.position.x?KeyCode.D:KeyCode.A);float elapsed=0;float maxDelta=0,maxExcess=0;bool clearedCrowdApproach=false;var previous=Player.transform.position;
 while(Mathf.Abs(Player.transform.position.x-x)>.16f&&elapsed<25){if(GamePause.IsPaused)yield return Foreground();if(School.chase.Step==SchoolChaseStep.Dead)Need(false,"chase actor died during route segment");
 if(School.chase.Route==SchoolChaseRoute.LowerEscape&&School.chase.CanUseCamera&&((!clearedCrowdApproach&&School.layout.CurrentRoom=="Floor02"&&Player.transform.position.x>13&&Player.transform.position.x<17)||(School.chase.EnemyActive&&School.chase.EnemyRoom==School.layout.CurrentRoom&&Vector2.Distance(School.chase.EnemyPosition,Player.transform.position)<6&&(School.layout.CurrentRoom!="Floor02"||Player.transform.position.x<17||Player.transform.position.x>23)))){clearedCrowdApproach=true;Input();var wanted=School.layout.Variant==SchoolWorldVariant.Memory?SchoolWorldVariant.Otherworld:SchoolWorldVariant.Memory;yield return CameraWorld(wanted);if(School.layout.Variant==SchoolWorldVariant.Memory&&School.layout.CurrentRoom=="Floor02")yield return CameraWorld(SchoolWorldVariant.Otherworld);Input(KeyCode.LeftShift,x>Player.transform.position.x?KeyCode.D:KeyCode.A);previous=Player.transform.position;}
 float delta=Mathf.Abs(Player.transform.position.x-previous.x);maxDelta=Mathf.Max(maxDelta,delta);maxExcess=Mathf.Max(maxExcess,delta-(float)(Player.WalkSpeed*Player.GetComponent<SprintAbility>().SpeedMultiplier)*Mathf.Max(Time.deltaTime,.02f));previous=Player.transform.position;elapsed+=GameplayClock.Delta;yield return null;if((Key(KeyCode.D)&&Player.transform.position.x>x)||(Key(KeyCode.A)&&Player.transform.position.x<x))break;}
 Input();Need(Mathf.Abs(Player.transform.position.x-x)<.35f,"native sprint reaches "+x);Check(maxExcess<.25f,"native route displacement matches speed and elapsed frame time "+x+" max delta="+maxDelta+" excess="+maxExcess);yield return Wait(.07f);
 }
